#include <vector>
#include <unordered_map>
#include <string>
#include <algorithm>
#include <climits>
using namespace std;

class Solution {
public:
    int minMirrorPairDistance(vector<int>& nums) {
        auto rev = [](int val) -> int {
            string s = to_string(val);
            reverse(s.begin(), s.end());
            return stoi(s);
        };
        unordered_map<int, int> last_seen;
        int min_dist = INT_MAX;
        for (int j = 0; j < (int)nums.size(); j++) {
            if (last_seen.count(nums[j])) {
                min_dist = min(min_dist, j - last_seen[nums[j]]);
            }
            last_seen[rev(nums[j])] = j;
        }
        return min_dist == INT_MAX ? -1 : min_dist;
    }
};

import java.util.*;

class Solution {
    private int rev(int val) {
        String s = new StringBuilder(String.valueOf(val)).reverse().toString();
        return Integer.parseInt(s);
    }

    public int minMirrorPairDistance(int[] nums) {
        Map<Integer, Integer> lastSeen = new HashMap<>();
        int minDist = Integer.MAX_VALUE;
        for (int j = 0; j < nums.length; j++) {
            if (lastSeen.containsKey(nums[j])) {
                minDist = Math.min(minDist, j - lastSeen.get(nums[j]));
            }
            lastSeen.put(rev(nums[j]), j);
        }
        return minDist == Integer.MAX_VALUE ? -1 : minDist;
    }
}

